do $$
declare v_course uuid; v_module uuid;
begin
select id into v_course from nexora.courses where title='Lógica de Programação Básica' limit 1;
select id into v_module from nexora.modules where course_id=v_course and position=5 limit 1;

update nexora.lessons set estimated_minutes=32,lab_type='pseudocode',lab_config=$json${"module":"Funções, listas e solução completa","pedagogy":"contrato-composicao-reuso-validacao","concept":"Extrair uma responsabilidade coesa para uma função com nome que expresse intenção.","checkpoint":{"question":"Qual função apresenta a responsabilidade mais clara?","options":["processarTudo()","fazerCoisas()","calcularTotalPedido(itens)","executar()"],"answer":2,"feedback":"Correto. O nome e a entrada deixam a responsabilidade observável.","feedback_incorrect":"Prefira uma função cujo nome explique a tarefa e cujo escopo seja específico."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"refactor_trigger","title":"Repetição de regra pede uma abstração","body":"Quando a mesma lógica de cálculo ou validação aparece em vários lugares, copiá-la aumenta o risco de versões divergentes. Uma função permite dar nome a uma responsabilidade e reutilizar sua implementação."},{"type":"concept","title":"Função é um contrato de tarefa","body":"Uma função recebe o que precisa, executa uma responsabilidade e pode produzir um resultado. O nome deve permitir entender a intenção sem abrir seu corpo."},{"type":"comparison","title":"Nome genérico × responsabilidade explícita","items":["`processar()` não diz o que acontece.","`calcularTotalPedido(itens)` comunica operação e dado necessário.","`validarCpf(cpf)` revela uma pergunta específica.","Uma função com muitos verbos no nome pode estar fazendo tarefas demais."]},{"type":"extraction","title":"Extraia uma regra duplicada","body":"Imagine três telas calculando desconto da mesma forma. Identifique os dados necessários, nomeie a tarefa e escreva pseudocódigo de uma função única. Depois substitua as três cópias por chamadas ao contrato."},{"type":"cohesion_check","title":"Uma função saudável tem um motivo claro para mudar","body":"Se alterar a regra de desconto exige modificar uma função de desconto, o acoplamento é compreensível. Se a mesma função também envia e-mail, grava banco e formata relatório, responsabilidades diferentes ficaram misturadas."},{"type":"practice","title":"Dê nome a três responsabilidades","body":"Para um sistema de matrícula, proponha funções separadas para validar idade, calcular investimento e formatar uma mensagem final. Defina o que cada uma precisa receber."},{"type":"professional_context","title":"Funções são fronteiras de manutenção e teste","body":"Responsabilidades pequenas e nomeadas são mais fáceis de testar, reutilizar, observar e substituir. Esse princípio aparece em serviços, componentes e APIs maiores."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=1;

update nexora.lessons set estimated_minutes=34,lab_type='data_model',lab_config=$json${"module":"Funções, listas e solução completa","pedagogy":"contrato-composicao-reuso-validacao","checkpoint":{"question":"Em `calcularDesconto(valor, taxa)`, o que `valor` e `taxa` representam na definição da função?","options":["Argumentos fixos.","Parâmetros do contrato.","Retornos.","Constantes globais obrigatórias."],"answer":1,"feedback":"Correto. Parâmetros descrevem as entradas esperadas pelo contrato.","feedback_incorrect":"Diferencie os nomes declarados pela função dos valores fornecidos em uma chamada."},"data_model":{"scenario":"Classifique os elementos de uma chamada `calcularDesconto(500, 0.1)`.","options":["Parâmetro","Argumento","Resultado esperado","Regra interna"],"rows":[{"label":"valor, taxa","value":"na definição","answer":0},{"label":"500","value":"na chamada","answer":1},{"label":"0.1","value":"na chamada","answer":1},{"label":"50","value":"após cálculo","answer":2}],"feedback":"Correto. Você separou contrato, valores concretos e saída.","feedback_incorrect":"Parâmetros pertencem à definição; argumentos são valores fornecidos na chamada."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"contract","title":"Parâmetros definem o que a função precisa saber","body":"`calcularFrete(valorPedido, cep)` declara dependências explícitas. O contrato fica mais reutilizável do que uma função que busca valores ocultos em variáveis globais."},{"type":"concept","title":"Parâmetro é o nome do contrato; argumento é o valor da chamada","body":"Na definição `somar(a, b)`, `a` e `b` são parâmetros. Na chamada `somar(4, 7)`, 4 e 7 são argumentos. Essa distinção ajuda a raciocinar sobre generalização."},{"type":"worked_example","title":"Uma função, vários pedidos","body":"`calcularDesconto(500, 0.10)` e `calcularDesconto(200, 0.05)` reutilizam a mesma regra estrutural com valores diferentes. O algoritmo deixa de depender de um único caso."},{"type":"dependency_check","title":"Passe apenas o que a tarefa realmente precisa","body":"Se uma função de cálculo exige nome, e-mail, endereço e telefone sem usá-los, o contrato está carregando dependências desnecessárias. Parâmetros demais podem indicar responsabilidade ampla demais."},{"type":"case_study","title":"Caso: preço final de curso","body":"Projete uma função que receba mensalidade e quantidade de meses para calcular investimento total. Depois explique se matrícula deveria ser outro parâmetro, uma constante ou responsabilidade de outra função conforme a regra escolhida."},{"type":"practice","title":"Generalize um cálculo concreto","body":"Transforme `total = 3 * 149.90` em uma função reutilizável. Defina parâmetros, duas chamadas diferentes e resultados esperados."},{"type":"mistake","title":"Global escondida enfraquece o contrato","body":"Uma função que depende de estado externo sem declarar essa dependência fica mais difícil de testar. Quando possível, faça entradas relevantes aparecerem no contrato."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=2;

update nexora.lessons set estimated_minutes=34,lab_type='pseudocode',lab_config=$json${"module":"Funções, listas e solução completa","pedagogy":"contrato-composicao-reuso-validacao","concept":"Usar retorno para produzir um valor que pode ser reutilizado por outras partes da solução.","checkpoint":{"question":"Qual diferença principal existe entre imprimir e retornar um total?","options":["Não existe diferença.","Retornar entrega o valor ao chamador para reutilização; imprimir apenas produz uma saída visível.","Imprimir sempre calcula melhor.","Retornar impede testes."],"answer":1,"feedback":"Correto. O retorno permite composição e teste do resultado.","feedback_incorrect":"Pense em qual opção disponibiliza o valor para outra expressão ou função."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"problem","title":"Mostrar um resultado não significa disponibilizá-lo","body":"Uma função pode imprimir `Total: 500`, mas outra parte do sistema ainda precisa do número 500 para calcular parcelamento. Retorno transforma o resultado em dado reutilizável."},{"type":"concept","title":"Retorno encerra o contrato com uma saída","body":"Uma função de cálculo idealmente retorna seu resultado para que o chamador decida se vai exibir, armazenar, comparar ou passar para outra função."},{"type":"composition","title":"Resultados podem alimentar novas operações","body":"`subtotal = calcularSubtotal(itens)`; `desconto = calcularDesconto(subtotal, taxa)`; `total = subtotal - desconto`. Cada função fornece uma peça verificável da solução."},{"type":"comparison","title":"Retornar × imprimir","items":["retornar produz valor para o chamador","imprimir é efeito de saída","função de cálculo tende a ser mais reutilizável quando não decide a apresentação","testes podem comparar diretamente o valor retornado"]},{"type":"early_return","title":"Retorno antecipado pode simplificar validações","body":"Uma função pode encerrar cedo para uma pré-condição inválida, desde que todos os caminhos tenham comportamento definido. O risco é retornar antes de aplicar uma regra necessária."},{"type":"practice","title":"Separe cálculo e apresentação","body":"Escreva pseudocódigo de `calcularMedia(notas)` que retorna um valor e de uma rotina externa que decide como mostrar esse resultado. Inclua o caso de lista vazia."},{"type":"test_design","title":"Teste o contrato pelo retorno","body":"Defina entradas e saídas esperadas para pelo menos três casos. Se a função exige observar console para saber se funcionou, o contrato pode estar difícil de testar."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=3;

update nexora.lessons set estimated_minutes=36,lab_type='data_model',lab_config=$json${"module":"Funções, listas e solução completa","pedagogy":"contrato-composicao-reuso-validacao","checkpoint":{"question":"Por que uma lista é melhor que criar `nota1`, `nota2`, ..., `nota30`?","options":["Porque listas eliminam qualquer necessidade de laço.","Porque representam vários elementos sob uma mesma estrutura percorrível.","Porque todos os valores precisam ser iguais.","Porque impedem lista vazia."],"answer":1,"feedback":"Correto. A coleção permite tratar elementos do mesmo papel de forma uniforme.","feedback_incorrect":"Procure a alternativa que modela um conjunto variável de elementos relacionados."},"data_model":{"scenario":"Classifique os elementos ao trabalhar com uma turma.","options":["Coleção","Elemento","Tamanho","Índice/posição"],"rows":[{"label":"notas","value":"[8, 6, 9]","answer":0},{"label":"notaAtual","value":"6","answer":1},{"label":"quantidade","value":"3","answer":2},{"label":"posição","value":"1","answer":3}],"feedback":"Correto. Coleção, elemento e metadados do percurso têm papéis diferentes.","feedback_incorrect":"Separe os valores agrupados do item atual e das informações sobre a coleção."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"scaling_problem","title":"Três variáveis funcionam; trinta revelam o problema","body":"`nota1`, `nota2`, `nota3` parecem simples até a quantidade variar. Uma lista modela elementos que compartilham o mesmo papel e permite percorrê-los com as mesmas operações."},{"type":"concept","title":"Lista é uma coleção ordenada","body":"A coleção possui elementos, tamanho e regras de acesso. O elemento atual não é a coleção inteira; ele é um valor selecionado durante acesso ou percurso."},{"type":"operations","title":"Perguntas naturais sobre coleções","items":["Quantos elementos existem?","Qual elemento está em determinada posição?","Existe algum elemento que satisfaz uma condição?","Quais elementos devem ser filtrados?","Como transformar cada elemento?"]},{"type":"case_study","title":"Turma com quantidade variável de notas","body":"Modele notas de uma turma sem saber previamente quantos alunos existem. Explique como calcular média, maior nota e quantidade de aprovados sem criar variáveis numeradas manualmente."},{"type":"edge_case","title":"Coleção vazia continua sendo uma coleção válida","body":"Funções que calculam média, mínimo ou primeiro elemento precisam definir o que acontece quando não existem elementos. Não deixe o caso vazio ser descoberto apenas em produção."},{"type":"practice","title":"Modele uma fila de atendimentos","body":"Defina uma lista com pelo menos quatro atendimentos. Para cada elemento, escolha os campos necessários para prioridade e tempo. Depois descreva quais operações serão feitas sobre a coleção."},{"type":"professional_context","title":"APIs e bancos entregam coleções o tempo todo","body":"Linhas de consultas, respostas de API e itens de interface frequentemente chegam como listas. Modelar e percorrer coleções conecta fundamentos à automação real."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=4;

update nexora.lessons set estimated_minutes=38,lab_type='logic',lab_config=$json${"module":"Funções, listas e solução completa","pedagogy":"contrato-composicao-reuso-validacao","concept":"Distinguir busca, filtro e transformação pela forma da saída produzida.","checkpoint":{"question":"Qual operação normalmente produz uma nova coleção contendo apenas elementos que satisfazem um critério?","options":["Buscar um único item.","Filtrar.","Somar.","Imprimir."],"answer":1,"feedback":"Correto. Filtro seleciona um subconjunto da coleção.","feedback_incorrect":"Procure a operação cujo resultado continua sendo uma coleção, porém com menos elementos."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"intent_first","title":"Comece pela pergunta que deseja responder","body":"Na mesma lista de produtos, você pode querer encontrar um produto específico, obter todos os disponíveis ou calcular preços com desconto. Busca, filtro e transformação têm intenções e saídas diferentes."},{"type":"concept","title":"A forma da saída ajuda a escolher a operação","items":["buscar → um elemento ou ausência","filtrar → subconjunto da coleção","transformar → nova coleção com um resultado para cada elemento"]},{"type":"case_study","title":"Produtos de uma loja","body":"Dada uma lista com nome, preço e estoque: encontre o produto de código X; filtre produtos com estoque > 0; transforme produtos em textos de exibição com nome e preço."},{"type":"comparison","title":"Não misture quatro intenções num único laço sem necessidade","body":"Um único percurso pode ser eficiente, mas juntar busca, filtro, soma e mutação em um bloco longo dificulta teste. Primeiro deixe a intenção correta; depois otimize se houver evidência."},{"type":"mutation_warning","title":"Transformar não precisa destruir a entrada","body":"Criar uma nova coleção preserva o dado original e reduz efeitos colaterais. Mutar elementos pode ser adequado em alguns contextos, mas deve ser decisão explícita."},{"type":"practice","title":"Escolha a operação pela saída","body":"Para uma lista de alunos, defina uma busca por CPF, um filtro de aprovados e uma transformação para gerar nomes em maiúsculas. Declare o tipo de saída esperado em cada caso."},{"type":"transfer","title":"Mesma ideia em SQL, planilhas e APIs","body":"WHERE se aproxima de filtro; localizar uma chave se aproxima de busca; SELECT com expressões pode transformar. Os conceitos atravessam ferramentas diferentes."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=5;

update nexora.lessons set estimated_minutes=42,lab_type='pseudocode',lab_config=$json${"module":"Funções, listas e solução completa","pedagogy":"contrato-composicao-reuso-validacao","concept":"Compor funções pequenas em um fluxo de responsabilidades observável e testável.","checkpoint":{"question":"Qual decomposição tende a ser mais testável?","options":["Uma função única que valida, calcula, imprime, grava e envia mensagem.","Funções separadas para validar, calcular e formatar, coordenadas por um fluxo principal.","Duplicar a regra em cada tela.","Usar apenas variáveis globais."],"answer":1,"feedback":"Correto. Responsabilidades separadas permitem validar cada etapa e o fluxo integrado.","feedback_incorrect":"Procure a arquitetura em que cada tarefa possui contrato e teste próprios."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"integration_problem","title":"Fundamentos viram sistema quando começam a conversar","body":"Variáveis, decisões, laços, funções e listas não são capítulos isolados. Uma solução real usa cada estrutura onde ela comunica melhor uma responsabilidade."},{"type":"pipeline","title":"Pense em fluxo de dados","items":["receber entrada","validar","modelar coleção","aplicar regras","agregar resultados","formatar saída"]},{"type":"worked_example","title":"Sistema de notas","body":"`validarNotas(notas)` → `calcularMedia(notas)` → `classificar(media)` → `formatarResultado(media, status)`. Cada função pode ser testada isoladamente e o fluxo pode ser testado de ponta a ponta."},{"type":"interface_contracts","title":"Composição exige contratos compatíveis","body":"Se uma função retorna texto quando a próxima espera número, o fluxo quebra. Defina claramente o que entra e sai de cada etapa."},{"type":"error_strategy","title":"Decida onde erros são tratados","body":"Validação pode retornar erro estruturado ou impedir avanço do pipeline. Evite que uma etapa posterior precise adivinhar se recebeu dado válido."},{"type":"practice","title":"Decomponha um processo comercial","body":"Modele um fluxo que recebe leads, valida telefone, filtra contatos válidos, conta quantos permanecem e gera um resumo. Defina funções e dados que conectam as etapas."},{"type":"architecture_bridge","title":"Esta lógica escala para sistemas maiores","body":"Serviços, componentes e pipelines continuam usando contratos, composição e separação de responsabilidades. A escala muda; os princípios permanecem."},{"type":"review","title":"Revise a solução por acoplamento","items":["Uma função conhece dados que não usa?","Uma etapa depende de efeito colateral oculto?","O retorno de uma função é adequado à próxima?","É possível testar cada responsabilidade sem montar o sistema inteiro?"]}]$json$::jsonb,updated_at=now() where module_id=v_module and position=6;

update nexora.lessons set estimated_minutes=55,lab_type='logic',lab_config=jsonb_set(coalesce(lab_config,'{}'::jsonb),'{checkpoint}',$json${"question":"Na triagem, qual etapa deve acontecer antes de classificar prioridade?","options":["Validar os dados do atendimento.","Ordenar por idade sem verificar valores.","Gerar a saída final.","Ignorar entradas inválidas."],"answer":0,"feedback":"Correto. Regras de prioridade só devem receber dados válidos.","feedback_incorrect":"A classificação não é confiável enquanto a entrada puder estar fora do domínio."}$json$::jsonb,true),content=$json$[{"type":"capstone_brief","title":"Projeto integrador: motor de triagem de atendimentos","body":"Você recebe uma lista de atendimentos com nome, idade, prioridade declarada, tempo estimado e status. O sistema deve validar entradas, classificar prioridade, ordenar ou selecionar casos relevantes e produzir um resumo verificável."},{"type":"requirements","title":"Requisitos mínimos","items":["separar dados válidos e inválidos","definir regra de prioridade com fronteiras explícitas","usar função para validação","usar função para classificação","percorrer a coleção","produzir ao menos duas métricas agregadas","tratar coleção vazia"]},{"type":"design_before_code","title":"Desenhe contratos antes do algoritmo final","body":"Defina assinaturas conceituais como `validarAtendimento(a)`, `calcularPrioridade(a)` e `gerarResumo(lista)`. Registre entradas, retornos e erros esperados."},{"type":"test_matrix","title":"Casos obrigatórios","items":["lista vazia","um atendimento válido","um inválido","duas prioridades diferentes","valor exatamente na fronteira","mistura de válidos e inválidos"]},{"type":"observability","title":"O resultado precisa explicar o que aconteceu","body":"Além da saída principal, registre quantidade processada, quantidade inválida e métricas escolhidas. Isso permite verificar o percurso sem ler cada iteração."},{"type":"refactor_round","title":"Faça uma segunda versão","body":"Depois que os testes passarem, procure duplicação, responsabilidades largas e nomes genéricos. Refatore mantendo a matriz de testes como proteção contra regressão."},{"type":"professional_review","title":"Revisão como se fosse entrega de equipe","items":["Outra pessoa entende os contratos?","Casos inválidos têm tratamento explícito?","As funções fazem tarefas coesas?","A coleção vazia foi considerada?","As fronteiras estão provadas?","O algoritmo explica seus resultados?"]},{"type":"course_mastery","title":"O que este desafio deve demonstrar","items":["modelagem de dados","expressões e fronteiras","decisões robustas","repetição e agregação","funções e retornos","coleções","testes antes da confiança","composição de uma solução completa"]}]$json$::jsonb,updated_at=now() where module_id=v_module and position=7;

update nexora.assessments set title='Checkpoint aplicado — Funções, coleções e composição', max_attempts=3 where course_id=v_course and module_id=v_module;
insert into nexora.learning_resources(course_id,module_id,title,resource_type,summary,content,position,status) select v_course,v_module,'Template — Contrato de função e pipeline','template','Modelo para especificar responsabilidades, parâmetros, retorno, erros e conexão entre funções antes de implementar.',$json${"sections":[{"title":"Contrato da função","items":["Nome e responsabilidade","Parâmetros e tipos conceituais","Retorno esperado","Pré-condições","Erros possíveis"]},{"title":"Casos de teste","items":["caso comum","fronteira","entrada vazia/inválida","resultado esperado"]},{"title":"Composição","items":["Qual função chama esta?","Quem consome o retorno?","Existe estado externo oculto?","A próxima etapa recebe o formato esperado?"]}],"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,5,'published' where not exists(select 1 from nexora.learning_resources where module_id=v_module and title='Template — Contrato de função e pipeline');
end $$;
